import{_ as a,o as n,c as i,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Profiles, friends and alliances","description":"","frontmatter":{"pageId":"players/community","contentRevision":5},"headers":[],"relativePath":"en/players/community.md","filePath":"en/players/community.md"}'),r={name:"en/players/community.md"};function s(o,e,l,c,d,p){return n(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="profiles-friends-and-alliances" tabindex="-1">Profiles, friends and alliances <a class="header-anchor" href="#profiles-friends-and-alliances" aria-label="Permalink to &quot;Profiles, friends and alliances&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>In <strong>Players → Social</strong>, edit your biography, invitation preferences and notifications. Find a player, request friendship, or create/join an alliance. Its owner invites members, transfers ownership or disbands it. Alliance chat is visible to current members from their join time and is not relayed to Discord.</p><p>The treasury accepts wallet contributions. The owner sets daily withdrawal allowances; spending is counted per UTC day and does not reset on leaving/rejoining. Leaving does not refund contributions; disbanding pays the entire balance to the current owner. Transfer ownership deliberately.</p><p>Allies are protected against mutual harmful attacks and incidents. Joining with conflicting queued hostility may be refused.</p><h2 id="social-consent" tabindex="-1">Profiles, invitations and alliances: managing consent <a class="header-anchor" href="#social-consent" aria-label="Permalink to &quot;Profiles, invitations and alliances: managing consent {#social-consent}&quot;">​</a></h2><p><strong>Players → Social</strong> opens a directory including offline players. Edit biography and invitation permission in your profile. Public fields include last activity/preferences, so put no secrets there.</p><p>Friendship/alliance membership requires invitation and acceptance. Senders can revoke, recipients refuse; closing invitations revokes waiting ones. A block in either direction removes friendship and pending invitations. Unblocking does not restore consent.</p><p>The alliance owner invites, grants treasury limits, transfers ownership and disbands. An owner must transfer or disband before leaving. Allies cannot launch harmful attacks against each other; joining may fail while mutual hostility is unresolved. Leaving does not erase an existing operation or its escrow.</p><h2 id="treasury" tabindex="-1">Treasury: a contribution is not a personal deposit <a class="header-anchor" href="#treasury" aria-label="Permalink to &quot;Treasury: a contribution is not a personal deposit {#treasury}&quot;">​</a></h2><p>Only wallet silver enters the treasury. Deposit physical stacks first. Treasury withdrawal credits a member&#39;s wallet; obtaining stacks still requires normal wallet withdrawal and mail.</p><p>Every member, including the owner, has permission and a UTC daily cap. New members receive no automatic withdrawal right. Leaving/rejoining and cap edits do not reset today&#39;s spending. Contributions create no refund entitlement: leaving pays nothing automatically, and disbanding sends <strong>the entire balance to the current owner</strong>.</p><p>Treasury wealth counts once for its owner. Withdrawal and ownership transfer with a nonempty balance check every member for debt/freeze/threat; an owner/member block also prevents withdrawal. Resolve unknown responses through the original outbox replay. The last 100 audit actions help reconcile results; do not manually repeat a transfer.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Biography: 500 characters; directory: up to 200 players; 100 friends, 16 alliance members, one alliance per player. Invitations expire in 7 days with up to 32 incoming/outgoing. Transactions cap at 1 billion, treasury at 1 trillion. Members&#39; freeze/debt/threat state may block withdrawal.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./chat-pings">Chat, messages and pings</a></li><li><a href="./guild-influence">Guild influence</a></li><li><a href="./economy">Wallet, mail and market</a></li></ul>',18)])])}const m=a(r,[["render",s]]);export{u as __pageData,m as default};
